"""Complete, private Yao1998 reader proposal. No source or Site writes."""
from pathlib import Path
from collections import Counter
from datetime import datetime, timezone
import json, hashlib, re

OUT=Path(__file__).resolve().parent
B=OUT.parent
SID='yao1998'; P='yao-1998-'
def read(p):return json.loads(p.read_text(encoding='utf-8'))
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def ev(p,where):return {'source_id':SID,'document_role':'main','pdf_page':p,'printed_page':594+p,'locator':f'Main PDF p. {p}, printed p. {594+p}, {where}'}
audit=read(B/'source-audit.json');identity=read(B/'source-identity.json');char=read(B/'characterization-draft.json');manifest=read(B/'crop-assets/manifest.json')
units={u['id']:u for u in audit['units']};rows={r['id'].removeprefix('char-'):r for r in char['measurement_rows']}
assert audit['source_sha256']==identity['main_sha256']==char['source']['sha256']==manifest['source_sha256']
drafts={p.stem:read(p) for p in sorted((B/'canonical-drafts').glob('*.json'))}
keys=['sample-a','sample-b','resin-conditioning','cadmium-loading','timepoint-workup','absorption','optical-microscopy','xrd','tem','characterization','other-electrolytes']
expected={k:('literature_protocol' if k in ['sample-a','sample-b'] else 'observation' if k in ['characterization','other-electrolytes'] else 'procedure') for k in keys}
sections=[{'id':k,'title':title,'items':[]} for k,title in [('precursors','Precursors'),('protocol','Synthesis protocol'),('structures','Final structures'),('properties','Properties'),('intuition','Chemical intuition'),('sources','Sources and limitations')]]
mapping={}
def title(prop):return prop.replace('_',' ').capitalize()
def fact(r):
    q=r.get('quantity');v=q.get('value') if q else r['fact']
    if q and 'lower_bound' in q:v=f"{q['lower_bound']}–{q['upper_bound']}"
    d={'id':r['id'],'label':title(r['property']),'value':v,'unit':q.get('unit') if q else None,'approximate':q.get('approximate',False) if q else False,'basis':r['basis'],'evidence':[ev(e['pdf_page'],e['locator']) for e in r['evidence']]}
    quals=[r.get('source_condition'),r.get('caveat')]
    if q and q.get('raw_text'):quals.insert(0,'Source wording: '+q['raw_text'])
    d['qualifier']=' '.join(x for x in quals if x)
    return d
def item(sec,key,name,text,source_units=(),records=(),samples=(),kind='reported_source_fact',row_keys=(),notes=(),evidence=()):
    ee=[]
    for uid in source_units:
        assert uid in units,uid
        for e in units[uid]['evidence']:ee.append(ev(e['pdf_page'],e['locator']))
        mapping.setdefault(uid,[]).append(key)
    for rk in row_keys:
        for e in rows[rk]['evidence']:ee.append(ev(e['pdf_page'],e['locator']))
    ee += [ev(p,w) for p,w in evidence]
    ee=list({json.dumps(e,sort_keys=True):e for e in ee}.values())
    assert ee,key
    links=[{'record_id':P+r,'json_pointer':'','relation':'Source-cohort or supporting-method association only. Identical bead, aliquot, preparation batch and cross-instrument specimen identity are not established.'} for r in records]
    scope={'formulations':list(samples),'physical_batch_id':None,'scope_kind':'source_cohort_or_spatial_region','state':name,'link_limit':'A source label or imaged depth links evidence to its cohort; it does not identify an independent synthesis batch or prove the same physical specimen across techniques.'}
    joins=[]
    for rec in records:
        for i,prod in enumerate(drafts.get(P+rec,{}).get('products',[])):
            if prod['sample_id'] in samples:joins.append({'record_id':P+rec,'sample_id':prod['sample_id'],'json_pointer':f'/products/{i}','relation':'Nominal source cohort or regional identity; exact physical specimen not established.'})
    if joins:scope['canonical_sample_links']=joins
    d={'id':key,'title':name,'text':text,'claim_type':kind,'sample_scope':scope,'evidence':ee,'source_locators':[e['locator'] for e in ee],'canonical_links':links,'notes':list(notes),'facts':[fact(rows[r]) for r in row_keys],'training_eligible':False}
    next(s for s in sections if s['id']==sec)['items'].append(d)
    return d
def cats(category,nums):return [f'{category}-{n:02}' for n in nums]

item('sources','source-identity','Article identity and reviewed scope','Hiroshi Yao, Yukako Takada and Noboru Kitamura published this study in Langmuir 1998, 14(3), 595–601. The article was received on May 8, 1997, revised to final form on November 14, 1997, and published online on February 3, 1998. The 1997 manuscript code does not change the publication year. All seven supplied main pages were read and visually inspected. Two local main files have identical content hashes; no matching SI was located or verified by the documented local checks.',cats('identity',[1,2,3]),kind='reviewed_source_identity',notes=('Missing local SI is not proof that publisher SI never existed.','The terminal article code is LA970480G.'))
item('precursors','host-polymer','Chelating polymer host','Chelex 100 is an Analytical Grade, 200–400 mesh styrene–divinylbenzene copolymer supplied by Bio-Rad. Its iminodiacetate groups, –CH₂N(CH₂COO⁻)₂, bind Cd²⁺. The cited manufacturer capacity is 2.0 mequiv/g for dry resin or 0.4 mequiv/mL for wet resin. These are host charge-capacity values, not nanocrystal yields. The actual product is CdS embedded in this host, rather than isolated CdS powder.',cats('chemical_inventory',[1,2]),records=('resin-conditioning','cadmium-loading','sample-a','sample-b'),samples=('sample-a','sample-b'),notes=('The polymer drawing is a chemical-connectivity reference. Crosslink fraction, molecular weight and exact atomic coordinates are not supplied.','Manufacturer manual is reference 18; its content was not independently opened here.'))
item('precursors','conditioning-solvents','Conditioning solvents and acid/base washes','Distilled water is used for resin soaking, aqueous precursor stocks, washing, no-salt pretreatment and wet optical measurements. Methanol precedes a 2 M aqueous HCl wash, followed by 2 M aqueous NaOH and thorough distilled-water washing. Ethanol treats the washed host before vacuum drying and is also used after water in product workup. Wash volumes, exposure times and solvent grades beyond the stated water quality are not reported.',cats('chemical_inventory',[3,4,5,6,7]),records=('resin-conditioning','timepoint-workup'),notes=('The reported eluent pH near 10 belongs to the conditioning wash; it is not a measured sulfide-reaction pH.',))
item('precursors','cadmium-stock','Cadmium loading solution','Cadmium acetate dihydrate, Cd(CH₃COO)₂·2H₂O, is GR grade from Kanto Chemical and is used as received. The loading solution is 5.0 mL of 8.4 × 10⁻³ M aqueous cadmium acetate for 0.107 g of dried polymer.',cats('chemical_inventory',[8]),records=('cadmium-loading',),notes=('The 0.107 g is dry host mass, not isolated CdS product mass.',))
item('precursors','sulfide-stock','Fresh aqueous sulfide feed','Sodium sulfide nonahydrate, Na₂S·9H₂O, is GR grade from Wako Pure Chemicals and is used as received. The source adds 100 mL of a freshly prepared 3.8 × 10⁻⁴ M aqueous Na₂S solution to the pretreated, Cd-loaded host under vigorous stirring.',cats('chemical_inventory',[9]),records=('sample-a','sample-b'),samples=('sample-a','sample-b'),notes=('Fresh preparation is specified; stock age limit, addition duration, concentration assay and solution pH are absent.',))
item('precursors','salt-pretreatment','NaCl pretreatment solution','NaCl is GR grade from Kanto Chemical and is used as received. Sample b is pretreated for 10 min with 10 mL of 0.5 M aqueous NaCl. The figures retain a nominal 0.5 M label even though 100 mL of aqueous sulfide is subsequently added; the final reaction-mixture concentration is not reconciled in the source.',cats('chemical_inventory',[10]),records=('sample-b',),samples=('sample-b',),notes=('The 10 mL salt solution replaces the no-salt water pretreatment; it is not an additional water charge.',))
item('precursors','alternative-salts','Other 1:1 electrolytes','Source note 25 reports similar visible absorption and CdS-layer width for LiCl, KCl and tetramethylammonium chloride, each labelled 0.5 M, compared with the NaCl preparation. Grades, exact amounts, separate spectra, numerical layer widths and complete preparation instructions are absent.',cats('chemical_inventory',[11])+cats('procedure',[14])+cats('observation',[15]),records=('other-electrolytes',),samples=('electrolyte-licl','electrolyte-kcl','electrolyte-tmacl'),kind='reported_supporting_comparison',row_keys=('other-electrolytes',),notes=('These are incomplete supporting comparisons rather than three fully specified additional synthesis routes.',))
item('precursors','hydrosulfide-speciation','Reactive sulfide species','Source note 15 describes Na⁺, HS⁻ and OH⁻ as the ionic species in the aqueous Na₂S solution under the present conditions. The mechanistic discussion therefore treats HS⁻ as the reactive diffusant. This does not introduce a separate sodium hydrosulfide reagent or a measured speciation fraction.',cats('chemical_inventory',[12]),records=('sample-a','sample-b'),kind='direct_source_note',notes=('No numeric reaction pH or acid–base speciation measurement is supplied.',))
item('sources','prior-host-systems','Earlier host systems and cited comparisons','Nafion, ethylene–methacrylic-acid copolymer, zeolites, porous glasses and organo-clay complexes are discussed as earlier nanocrystal hosts. PbS also belongs to this background. Dowex A-1 is mentioned only as an iminodiacetate resin comparison for Na⁺ diffusion. These materials are not additional products synthesized in the present article.',cats('chemical_inventory',[13]),kind='cited_prior_context')

item('protocol','resin-conditioning','Resin conditioning','Soak the Chelex host in distilled water. Wash sequentially with methanol, 2 M aqueous HCl, 2 M aqueous NaOH and thoroughly with distilled water; the eluent is reported near pH 10. Treat with ethanol, dry under vacuum and store. The authors emphasize careful cleaning for reproducibility.',cats('procedure',[1,2]),records=('resin-conditioning',),notes=('Wash quantities, durations, vacuum pressure, drying temperature/time and storage conditions are unreported.',))
item('protocol','cadmium-loading','Cadmium loading','Add 0.107 g of dry resin to 5.0 mL of 8.4 × 10⁻³ M aqueous cadmium acetate. Sonicate for 10 min and store for 2 days at room temperature. Wash the Cd-loaded particles with distilled water several times.',cats('procedure',[3,5]),records=('cadmium-loading',),notes=('The reported adsorbed Cd²⁺/total adsorption-capacity ratio is approximately 0.4.','Room temperature explicitly describes storage; sonication power and temperature, wash counts and separation apparatus are not specified.'))
item('protocol','loading-test','Qualitative loading and retention checks','The authors judge Cd²⁺ incorporation from the absence of CdS formation when the supernatant is challenged with HS⁻. They also report no Cd²⁺ elution during NaCl pretreatment. These are qualitative source statements, without an assay detection limit or calibrated fraction.',cats('procedure',[4,12]),records=('cadmium-loading','sample-b'),notes=('Do not convert either statement into 100% quantitative uptake, zero released concentration or an isolated yield.',))
item('protocol','sample-a-pretreatment','Sample a: water pretreatment','Disperse the Cd-loaded particles in 10 mL of distilled water for 10 min before adding sulfide. This is the no-added-NaCl preparation, labelled sample a.',cats('procedure',[6]),records=('sample-a',),samples=('sample-a',),notes=('The polymer mass is defined in the shared loading procedure rather than repeated in this sentence of the source.',))
item('protocol','sulfide-addition','Sulfide addition and color development','Add 100 mL of freshly prepared 3.8 × 10⁻⁴ M aqueous Na₂S under vigorous stirring. A pale yellow color develops slowly in sample a; color development is faster in sample b. The source does not specify injection speed, vessel geometry or a separate reaction temperature.',cats('procedure',[7]),records=('sample-a','sample-b'),samples=('sample-a','sample-b'))
item('protocol','stir-and-stand','Stirring and standing sequence','Stir for 2 h and then allow the suspension to stand for 2 days at room temperature. This preparative sequence is distinct from the elapsed times used to label optical measurements. The apparent optical plateau within 2 h for sample b does not remove the subsequent standing step.',cats('procedure',[8,13]),records=('sample-a','sample-b'),samples=('sample-a','sample-b'),notes=('No numerical room temperature, stirring speed, light condition, atmosphere or pressure is given.','The 48 h Figure 1 spectrum is labelled by reaction time; it is not automatically the same clock as the end of a 2 h plus 2 day workup sequence.'))
item('protocol','sample-b-pretreatment','Sample b: electrolyte pretreatment','Use the analogous sample-a procedure, but first pretreat the Cd-loaded polymer for 10 min in 10 mL of 0.5 M aqueous NaCl. Add the sulfide solution afterward. The source explicitly permits the analogous stirring, standing and workup sequence, while the NaCl pretreatment replaces the water pretreatment.',cats('procedure',[11]),records=('sample-b',),samples=('sample-b',),notes=('No additional 10 mL water charge is inferred. Final salt molarity remains unresolved.',))
item('protocol','timepoint-workup','Time-dependent aliquots and isolation','For the absorption time course, remove several-milliliter aliquots at various times after mixing. Remove the supernatant, wash the retained particles thoroughly with water and ethanol, then dry under vacuum. Exact aliquot volumes, sampling times, washing repetitions and the supernatant-removal apparatus are not stated.',cats('procedure',[9,10]),records=('timepoint-workup','sample-a','sample-b'),samples=('sample-a','sample-b'),notes=('Do not depict an unreported centrifuge or filtration step. Whether sequential aliquots deplete the same preparation batch is unknown.',))
item('protocol','pretreatment-diffusion-context','Rationale for the 10 min pretreatment','The authors give a cited Na⁺ diffusion coefficient of 1.2 × 10⁻⁷ cm²/s immediately after naming Chelex 100, and describe Dowex A-1 as similar. They consider 10 min sufficient for Na⁺ redistribution through approximately 100 µm host particles. This comparison is not a measured HS⁻ diffusion coefficient for the present composites.',cats('observation',[21]),records=('sample-b','characterization'),kind='cited_method_rationale',row_keys=('na-diffusion',))
item('sources','prior-concentrated-sulfide','Prior concentrated-sulfide experiment','The discussion cites earlier work in which approximately 10⁻² M aqueous Na₂S generated CdS more homogeneously throughout the host. This is used to argue that host structure or Cd-loading inhomogeneity alone cannot explain the present radial gradient. Host-size and sulfide-injection variants also belong to that earlier study.',cats('procedure',[15])+cats('author_model',[1]),kind='cited_prior_experiment',notes=('Reference 14 is not independently read here, and no complete additional recipe is reconstructed from this comparison.',))

item('structures','xrd-method','X-ray diffraction acquisition','A Rigaku RINT 2000 diffractometer measures the samples using Cu Kα radiation at 0.154 nm over 2θ = 20–60°. Source-reported XRD results are retained below even though the article prints no original diffraction pattern.',cats('characterization_method',[5]),records=('xrd','characterization'),samples=('sample-a','sample-b'),row_keys=('xrd-scan','xrd-radiation'),notes=('Voltage/current, step size, scan rate, specimen preparation, calibration and raw intensities are absent.',))
item('structures','xrd-phase','CdS phase assignment','The authors describe a broad, intense reflection at 2θ = 26.5° and very weak peaks near 44° and 52°, assigning them to (111), (220) and (311) of zinc-blende, cubic CdS. This describes the inorganic component of a CdS/polymer composite. No lattice refinement, phase fraction, CIF or measured atomic coordinates are provided.',cats('observation',[4]),records=('xrd','characterization'),samples=('sample-a','sample-b'),kind='reported_pattern_features_and_author_assignment',row_keys=('xrd-111','xrd-220','xrd-311','phase'),notes=('References 6, 22 and 23 are cited context. A text excerpt is available; an absent XRD plot is not reconstructed.',))
item('structures','xrd-size','XRD-derived mean dimensions','Gaussian fitting of the 26.5° reflection followed by a Debye–Scherrer-type calculation gives mean dimensions of 3.8 nm for sample a and 3.1 nm for sample b. These source-derived diffraction estimates have different averaging and spatial scope from the regional TEM distributions.',cats('observation',[5]),records=('xrd','characterization'),samples=('sample-a','sample-b'),kind='author_derived_diffraction_estimates',row_keys=('sample-a-xrd-mean','sample-b-xrd-mean'))
item('structures','tem-method','Cross-sectional TEM acquisition','The low-magnification instrument is a Hitachi H-300; high-magnification images use a JEOL JEM 2010. Thin cross sections were necessary for the swelling polymer host, and the authors describe their preparation as difficult. The source does not give an embedding medium, microtome, section thickness, grid, accelerating voltage or exact particle counts.',cats('procedure',[16])+cats('characterization_method',[6]),records=('tem','characterization'),samples=('sample-a','sample-b'),notes=('Figures 3 and 7 have 250 nm scale bars; Figure 4 has 50 nm scale bars. No SAED or lattice-fringe indexing result is supplied.',))
item('structures','sample-a-depths','No-salt spatial distribution','Figure 3 compares the surface, a region approximately 4–5 µm inward and a region approximately 8–9 µm inward in sample a. The lower image direction points into the host. CdS formation is described as terminating about 8–10 µm below the surface; no crystals were observed at the host center.',cats('observation',[6]),records=('tem','characterization','sample-a'),samples=('sample-a','a-surface','a-depth4um','a-depth8um'),row_keys=('a-depth4um-depth','a-depth8um-depth','a-layer-end','a-center'))
item('structures','crystals-and-aggregates','Constituent crystals and aggregates','Near the surface of sample a, no CdS flocculation is observed. At 4–5 µm inward, approximately 4–7 nm constituent nanocrystals form aggregates described as several tens of nanometers. The qualitative discussion summarizes many roughly 3 nm surface crystals and fewer roughly 5 nm interior crystals; these rounded trends are not new independent experiments.',cats('observation',[7,14]),records=('tem','characterization'),samples=('a-surface','a-depth4um'),row_keys=('a-surface-flocculation','a-inner-crystals','a-inner-aggregates','a-surface-qual-size','a-inner-qual-size'))
item('structures','regional-histograms','Regional size distributions','Figure 5a fits the near-surface TEM histogram with a log-normal distribution, mean 2.7 nm and reported standard deviation 0.4. The unit and mathematical definition of this standard deviation are absent. Figure 5b fits a normal distribution approximately 4 µm inward, mean 4.6 nm and standard deviation 1.8 nm. Neither fit is a whole-bead TEM size label.',cats('observation',[8,9]),records=('tem','characterization'),samples=('a-surface','a-depth4um'),kind='reported_histograms_and_fitted_distributions',row_keys=('a-surface-hist-mean','a-surface-hist-sd','a-inner-hist-depth','a-inner-hist-mean','a-inner-hist-sd'),notes=('Histogram counts were not digitized, and no exact total number of counted crystals is inferred.',))
item('structures','optical-layer-image','Optical ring and layer-width definition','A Sony DXC-930 CCD camera attached to the microscope records single-particle optical images, using a Mitsubishi CP-11 video printer. Figure 6a shows the no-salt host with a 25 µm scale bar. A ring about 8 µm inside the surface is associated with the inner CdS boundary by comparison with TEM. Figure 6b defines L as the distance from the bead surface to this ring.',cats('characterization_method',[4])+cats('observation',[10]),records=('optical-microscopy','characterization'),samples=('sample-a',),row_keys=('a-ring-depth','l-definition'),notes=('The optical photograph and definition schematic are different evidence types, not two independent experiments.',))
item('structures','sample-b-depths','Salt-treated spatial distribution','Sample b has a wider CdS-containing layer. Figure 7 shows no observed flocculation at the surface; slight flocculation but comparatively homogeneous dispersion at 9–10 µm inward; and clear flocculation alongside isolated small nanocrystals at 15–16 µm. The source contrasts pronounced flocculation at 8–9 µm in a with its occurrence deeper in b.',cats('observation',[12,13]),records=('tem','characterization','sample-b'),samples=('sample-b','b-surface','b-depth9um','b-depth15um'),row_keys=('b-depth9um-depth','b-depth15um-depth','sample-b-surface','sample-b-middle','sample-b-deep','b-larger-L'),notes=('The deepest imaged region is not a measured terminal layer width. The salt-treated sample is not entirely free of flocculation.',))

item('properties','absorption-method','Single-particle absorption measurements','The system combines a Nikon Optiphoto 2 microscope, Oriel Multispec 257 polychromator and Princeton Instruments ICCD-576E/G detector. A 150 W Xe lamp, Hamamatsu L2273, provides illumination. Water redispersement reduces scattering from dried beads; selected water-swollen hosts measure 100–110 µm. Details of the microspectroscopy setup are cited to references 20 and 21.',cats('characterization_method',[1,2,3]),records=('absorption','characterization'),samples=('sample-a','sample-b'),row_keys=('host-wet-diameter','lamp-power'),notes=('Lamp power is not sample irradiance or dose. Spectral resolution, path length and a scattering-correction calibration are not reported.',))
item('properties','absorption-reproducibility','Monitoring wavelength and reproducibility','At fixed host diameter and reaction time, the source reports spectra reproducible within ±5%. Time profiles use absorbance at 450 nm, described as near the excitonic shoulder only in the qualified size/time regime. It is not an exact absorption onset or a band-gap measurement.',cats('characterization_method',[7,8]),records=('absorption','characterization'),samples=('sample-a','sample-b'),row_keys=('spectrum-reproducibility','monitor-wavelength'),notes=('No replicate count or point-specific uncertainty model is supplied.',))
item('properties','spectral-comparison','Spectra at 30 min and 48 h','Figure 1a shows that sample b has higher absorbance below 500 nm after 30 min, which the authors interpret as greater early CdS formation. Figure 1b shows a blue-shifted salt-treated spectrum at 48 h, consistent with a smaller characteristic size. The two figure panels are time points; they do not themselves denote source samples a and b.',cats('observation',[1,2]),records=('absorption','characterization'),samples=('sample-a','sample-b'),kind='reported_optical_comparison_and_author_interpretation',row_keys=('30min-optical','48h-optical'),notes=('No numerical onset, band gap, peak position, concentration or isolated yield is recovered from the plotted curves.',))
item('properties','long-time-profile','Absorbance time course','Both cohorts show a rapid 450 nm absorbance increase during the first 2 h. Sample b is interpreted as completing formation within that interval, whereas a continues increasing gradually up to 48 h. This is optical reaction-progress evidence, not a measured completion fraction or direct crystal count.',cats('observation',[3]),records=('absorption','characterization'),samples=('sample-a','sample-b'),row_keys=('first2h-optical','sample-b-plateau','sample-a-continuation'),notes=('Figure 2 uses filled symbols for sample b and open symbols for a, opposite to Figures 8 and 9.',))
item('properties','early-time-profile','Early absorbance scaling','The authors distinguish the initial difference at t < 30 min from detailed measurements at t < 10 min. At a given early time, the band shapes are nearly the same for the two samples. Linear fits of absorbance at 450 nm against √t give slopes 4.6 × 10⁻³ s⁻¹ᐟ² for a and 8.9 × 10⁻³ s⁻¹ᐟ² for b.',cats('observation',[16,17]),records=('absorption','characterization'),samples=('sample-a','sample-b'),kind='reported_spectral_comparison_and_fit',row_keys=('early-shape','sample-a-sqrt-time-slope','sample-b-sqrt-time-slope'),notes=('These are slopes of absorbance versus square-root time. They are not a concentration-production rate or dA/dt.','Figure 8 uses filled circles and a solid line for a; open circles and a dashed line for b.'))
item('properties','layer-calibration','Absorbance and CdS-layer width','L changes with reaction time. Below approximately 4 µm the optical ring cannot be located precisely. In the analyzed region, sample a and b follow a common linear relation between absorbance at 450 nm and observed L. The authors infer similar CdS density at a given absorbance and use that relation to estimate L(t).',cats('observation',[18,19]),records=('absorption','optical-microscopy','characterization'),samples=('sample-a','sample-b'),kind='reported_correlation_and_author_inference',row_keys=('l-resolution','a-L-correlation'),notes=('No numerical regression coefficient or intercept is supplied. Poor precision below 4 µm is not evidence that a thinner layer is absent.',))
item('properties','diffusion-estimates','Optically inferred hydrosulfide diffusion','Combining the absorption-to-L relation with L = √(2Dt), the authors calculate effective HS⁻ diffusion coefficients of 2.5 × 10⁻¹⁰ cm²/s for sample a and 1.1 × 10⁻⁹ cm²/s for sample b. These values depend on the reactive-layer proxy and quasi-linear diffusion model.',cats('observation',[20]),records=('characterization',),samples=('sample-a','sample-b'),kind='author_calculated_effective_transport',row_keys=('sample-a-effective-HS-diffusion','sample-b-effective-HS-diffusion'),notes=('These are not tracer measurements, free-water diffusivities or the cited Na⁺ resin value.',))
item('properties','earliest-time-limit','Limit of the 450 nm proxy','Source note 27 warns that the very small CdS crystals formed at the earliest times do not make 450 nm absorbance a valid exciton-absorption measure. The authors restrict quantitative interpretation to the t and L regions discussed in the paper; an exact earliest-time cutoff is not supplied.',cats('observation',[22]),records=('absorption','characterization'),samples=('sample-a','sample-b'),kind='direct_source_note',row_keys=('earliest-optical-limit',))

item('intuition','radial-nucleation','Transport and local supersaturation','The authors propose that HS⁻ consumption during inward transport produces high surface supersaturation and many nuclei, followed by lower interior supersaturation and fewer nuclei. This creates small crystals near the surface and growth-dominated larger crystals deeper in the bead. Chelating ligands and local Cd²⁺ depletion may further restrict surface growth.',cats('author_model',[2,3])+cats('intuition',[1,3]),records=('characterization',),samples=('sample-a','sample-b'),kind='original_author_interpretation',notes=('No direct local HS⁻ concentration, nucleus count, ligand binding constant or supersaturation profile is measured.','Reference 26 is cited for the nucleation/growth context.'))
item('intuition','salt-screening','Why electrolyte changes growth','The authors connect faster inward HS⁻ transport under added NaCl to more nuclei, smaller nanocrystals and earlier local depletion of Cd²⁺ and HS⁻. This would suppress later growth while distributing CdS deeper in the host. The result is specific to a chelating, confining matrix and contrasts with salt-induced flocculation expected for homogeneous aqueous colloids.',cats('author_model',[4])+cats('intuition',[2]),records=('characterization',),samples=('sample-a','sample-b'),kind='original_author_interpretation',notes=('The homogeneous-solution contrast is cited background from reference 17 rather than a separately measured control here.',))
item('intuition','ring-contrast','Origin of the visible ring','The authors attribute the optical ring to the nonuniform CdS distribution. CdS and polymer have different refractive indices, and the partly flocculated inner layer changes scattering across the boundary. This explains why an optical image can report a distribution depth rather than just host shape.',cats('observation',[11]),records=('optical-microscopy','characterization'),samples=('sample-a',),kind='original_author_interpretation',notes=('Reference 24 supplies scattering context; no numerical refractive index or optical-scattering model fit is reported.',))
item('intuition','swelling-alternative','Swelling as an alternative explanation','Added electrolyte would reduce the osmotic-pressure difference and suppress swelling. Smaller pores would ordinarily slow ion diffusion, opposite to the faster optically inferred HS⁻ transport. The authors therefore reject swelling alone as the cause of the observed acceleration.',cats('author_model',[5]),records=('characterization',),kind='original_author_interpretation',notes=('Reference 28 is cited. No salt-dependent pore size or actual swelling ratio is measured.',))
item('intuition','donnan-mechanism','Donnan partitioning mechanism','The source applies a charged-membrane Donnan model to the cation-exchange host. Without added NaCl, Na⁺ redistribution toward water makes the polymer surface more negative and limits inward HS⁻ transport. With NaCl, Na⁺/Cl⁻ partitioning reduces the magnitude of that barrier. The cited Cd²⁺/Na⁺ resin selectivity is approximately 10⁷, which is used to argue against easy Na⁺ displacement of bound Cd²⁺.',cats('author_model',[6,7,8]),records=('characterization',),kind='original_author_model_with_cited_inputs',row_keys=('selectivity',),notes=('References 18 and 29–32 are source-cited; no direct potential measurement or DFT calculation is supplied.',))
item('intuition','donnan-variables','Donnan equations and variable definitions','Equations 1–3 relate the polymer–water potential difference to ion partitioning and fixed charge. B is counterion (cation) concentration; A is co-ion (anion) concentration; i and o identify polymer and water; X is fixed charge; C is the external 1:1 electrolyte concentration. R, T and F are the gas constant, temperature and Faraday constant. The model assumes electroneutrality: Bᵢ = Aᵢ + X and Bₒ = Aₒ ≡ C.',records=('characterization',),kind='original_author_model',evidence=((7,'Equations 1–3 and definitions'),),notes=('A numerical model temperature is not stated.','The supplied main contains three numbered equations; the diffusion-length relation in the body is unnumbered.'))
item('intuition','donnan-values','Reported model potentials and sensitivity','Using wet-polymer fixed charge X = 0.4 equiv/L, the source calculates −390 mV without added NaCl and −10 mV for its 0.5 M NaCl label. A hypothetical reduction of swelling to one-third changes the reported result to −26 meV. The last unit is printed as an energy unit, unlike the surrounding potential units, and is retained as a source conflict.',cats('author_model',[9,10]),records=('characterization',),kind='original_author_model_not_measured_property',row_keys=('donnan-fixed-charge','donnan-no-salt','donnan-salt','donnan-swelling'),notes=('For the no-added-NaCl case, the finite background-ion concentration C used in the model is not supplied. Setting C = 0 does not reproduce the reported finite value.','One-third swelling is an assumption, not a measured change.'))
item('intuition','diffusion-relation','Diffusion-length approximation','The unnumbered relation Δ = √(2Dt) defines Δ as a diffusion length and D as the HS⁻ diffusion coefficient in the host. The later analysis substitutes the observed/optically estimated CdS-layer width L in the relation L = √(2Dt). This connects an optical reaction-progress proxy to an effective transport parameter, rather than directly tracking individual ions.',records=('characterization',),kind='original_author_model',evidence=((5,'Unnumbered diffusion-length relation'),(6,'L = (2Dt)^(1/2) and inferred coefficients')),notes=('The reactive, radial host and the qualified optical range limit the interpretation.',))
item('intuition','note33-model-limits','Limits of theoretical diffusion estimates','Note 33 discusses approximate anion transport using a noncharged-polymer diffusion coefficient D₀, distribution coefficient Q₀ and transport number t₀. Exact values could not be estimated because Q₀ and t₀ were not precisely available. The note refers to a positively charged polymer, whereas the main discussion describes a negative-surface, cation-exchange host; that wording difference remains explicit.',cats('author_model',[11]),records=('characterization',),kind='direct_source_note_and_model_limit',notes=('The qualitative screening argument does not constitute an independent numerical prediction matching the optical-derived diffusion values.',))
item('intuition','design-outlook','Controls suggested by the study','The authors propose electrolyte addition as another means of controlling embedded-CdS size and distribution, alongside host size and sulfide injection method discussed in earlier reference 14. Possible functional-material or device uses are prospective rather than tested performance claims.',cats('author_model',[12]),kind='original_author_outlook')
item('intuition','measurement-scope','Combining measurements without losing sample scope','XRD averages a diffraction response, TEM measures selected cross-sectional regions and optical spectroscopy samples individual swollen hosts. These observations can support a common mechanism while retaining different size definitions, times and spatial populations. A single size label would erase the paper’s central distinction.',cats('intuition',[4]),kind='curator_synthesis_of_source_evidence')
item('intuition','future-questions','Measurements that could resolve remaining ambiguity','Future work could separately establish the final salt concentration, wet swelling, local ion profiles and polymer potential. This would help distinguish ion screening from geometric or concentration effects. These are curator-proposed follow-up questions, not experiments performed in the source.',cats('intuition',[5]),kind='curator_proposed_outlook')
item('intuition','dataset-implications','Data fields required by the host system','The evidence requires separate fields for resin charge capacity and dry/wet state, pretreatment, host versus nanocrystal size, radial depth, aliquot timing, optical proxies and model-derived parameters. These distinctions preserve information that would be lost in a simple reaction-temperature-to-size pair.',cats('intuition',[6]),kind='curator_dataset_interpretation')

# Human-readable source qualifications preserve the independent audit's complete scope.
CONFLICTS=[
('Salt stock and mixture concentration','A 10 mL, 0.5 M NaCl pretreatment precedes 100 mL sulfide addition, but the figures and model retain a 0.5 M salt label. Extra salt or stock-to-mixture handling is not documented. Assuming only additive volumes and no extra salt would calculate approximately 0.04545 M, but that is a conditional curator calculation, not a reported correction.'),
('Preparative and measurement clocks','The preparative 2 h stirring plus 2 days standing sequence is not identical to the 48 h reaction-time label in Figure 1b. Keep these clocks separately; do not turn the 48 h spectrum into a 50 h measurement or replace the stated protocol.'),
('Unreported step temperatures','Room temperature explicitly applies to the 2 day storage and standing periods. Temperatures during sonication, pretreatment and stirring are not separately specified. Do not assign 25 °C or inherit a numeric temperature.'),
('Dry host, swollen bead and CdS sizes','The 0.107 g quantity is dry resin mass. Dry and wet capacities have different bases. A 100–110 µm swollen bead is not a roughly 3 nm CdS crystal, and neither value is a product mass yield.'),
('Absorbance versus formation rate','Figure 8 fits absorbance against √t. The abstract’s formation-rate phrasing does not convert the ordinate to dA/dt or a concentration-production rate.'),
('Undefined log-normal spread unit','Figure 5a reports a log-normal standard deviation of 0.4 without specifying its unit or parameterization. Retain the source value with unit undefined rather than labelling it nm or log-space by assumption.'),
('Method-specific size populations','The XRD values 3.8/3.1 nm and local TEM fits 2.7/4.6 nm have different sampling and analysis scopes. No same-time, same-batch or whole-bead TEM mean is established.'),
('Depth labels and precision','TEM captions say 4–5 µm, while the histogram says approximately 4 µm. Likewise 8–9 µm, terminal depth 8–10 µm and optical ring depth near 8 µm have distinct locators. They do not specify section thickness or exact co-registration.'),
('Potential unit inconsistency','The hypothetical swelling example prints −26 meV for Δφ, while the other model values use mV. Retain the energy-unit conflict without silently normalizing it.'),
('Zero added salt is not zero ionic concentration','The Na₂S solution itself supplies ions. Equation 3 is undefined at C = 0, yet a finite −390 mV is reported for zero added NaCl. The effective background C and numeric model temperature are unreported.'),
('Polymer charge wording','Note 33 mentions a positively charged polymer, while the main text describes a cation exchanger and negative surface potential. Preserve the source ambiguity rather than drawing a contradictory charged-host model.'),
('Figure-specific symbol identities','Figure 2 uses filled symbols for sample b and open symbols for a. Figures 8–9 use filled symbols for a and open symbols for b. Each original legend controls its own sample mapping.'),
('Visual resolution of extraction glyphs','The source images resolve Cu Kα, ±5%, square roots and HS⁻ signs that can be corrupted in plain extraction. These visual corrections preserve chemical identity; they do not introduce new measured values.'),
('Different transport quantities','The cited Na⁺ value 1.2 × 10⁻⁷ cm²/s, optical-derived HS⁻ values 2.5 × 10⁻¹⁰ and 1.1 × 10⁻⁹ cm²/s, and absorbance-versus-√t slopes 4.6/8.9 × 10⁻³ s⁻¹ᐟ² are different quantities and cannot share one diffusivity field.'),
('Unknown specimen joins','Exact aliquot identities, sampling schedule, TEM reaction times and XRD specimen history are absent. Nominal formulation and depth labels support source-cohort joins, not a claim that all figures show the same physical experiment.'),
('Characterization not supplied','No original XRD pattern, electron diffraction/SAED pattern, Raman spectrum, PL/quantum yield, thermal-stability curve, atomic coordinates, CIF or computed interface is supplied. The narrative XRD assignments remain available as text evidence.'),
('Cited variants versus direct comparisons','Reference 14’s concentrated-sulfide, host-size and injection variants are earlier-work context. Note 25’s alternative salts are direct reported comparisons, despite appearing in a footnote. Their evidentiary roles differ.'),
('Composite identity','Water disperses swollen CdS-containing host beads, and TEM examines their cross sections. The source does not describe free-standing uncapped CdS nanocrystals or an atomically uniform CdS shell/interface.'),
]
for n,(name,text) in enumerate(CONFLICTS,1):item('sources',f'conflict-{n:02}',name,text,[f'conflict-{n:02}'],kind='source_conflict_or_semantic_limit')

